// IES floodlights, on the carts through romdev, GL and WebGPU: derby's four corner floods (arena 1 at dusk) and
// pugball's night ring (stadium 2) are shaped by the games' IES profiles (assets/lights/flood.ies, generated by each
// game's tools/make-ies.mjs). The match is paused at a fixed moment and drawn with the profiles and without them
// (the control: derby `sw no_ies 1`, pugball `sw ies 0`):
//   - with them the engine draws every lit flood with its profile (debug field lights.ies, the lighting stats' ies:
//     derby 4, pugball 4 or more), without them none (0): the count check, which the control fails
//   - the two pictures differ (the profile changes where the light falls: at least 0.2% of pixels by more than 16 levels)
//   - the profiled picture is not darker (mean level at least 98% of the plain one's): the floods still light the play
// Both frames are kept to look at (out/ies-floods).
//   node tests/ies-floods.mjs [--gl] [--webgpu] [--games derby,pugball]
import { ROMDEV_URL } from './lib/romdev-url.mjs';
import { mkdirSync } from 'node:fs';
import { resolve, dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { request } from 'node:http';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..'), SESSION = 'ies-floods', OUT = join(ROOT, 'out/ies-floods');
const arg = (n, d) => { const i = process.argv.indexOf(n); return i > 0 ? process.argv[i + 1] : d; };
const BACKENDS = process.argv.includes('--gl') ? ['gl'] : process.argv.includes('--webgpu') ? ['webgpu'] : ['gl', 'webgpu'];
const GAMES = arg('--games', 'derby,pugball').split(',');
mkdirSync(OUT, { recursive: true });
let requests = 0;
const post = (name, body) => new Promise((ok, no) => {
  requests++;
  const q = request(`${ROMDEV_URL}/tool/${name}`, { method: 'POST', headers: { 'Content-Type': 'application/json', 'x-romdev-session': SESSION, 'x-romdev-agent': SESSION } }, (res) => {
    let t = '';
    res.setEncoding('utf8');
    res.on('data', (c) => (t += c));
    res.on('end', () => ok({ status: res.statusCode, text: t }));
  });
  q.on('error', no);
  q.end(body);
});
const bye = async (code) => {
  try { await post('host', '{"op":"shutdown"}'); } catch {}
  console.log(`romdev requests: ${requests}`);
  process.exit(code);
};
const tool = async (name, args) => {
  let r;
  try { r = await post(name, JSON.stringify(args)); }
  catch (e) { console.error(`romdev ${name}: ${e.message} (the server is down)`); await bye(3); }
  let j; try { j = JSON.parse(r.text); } catch { j = r.text; }
  if (r.status !== 200 || j?.error) { console.error(`romdev ${name}: ${r.text.slice(0, 400)}`); await bye(3); }
  return j;
};
const cmd = async (text, maxFrames = 8) => (await tool('wasm', { op: 'command', text, maxFrames })).reply;
const load = (game, backend) => tool('loadMedia', { platform: 'wasmcart', path: join(ROOT, `build/cart-wgpu/carts/${game}.wasc`), gpuPower: 'low-power', ...(backend === 'gl' ? { wgpu: false } : {}) });
import { readImage } from '../deps/cartwheel-engine/tools/lib/png.mjs';
const GAME = {
  derby: { start: 'bout 1', settle: 300, cam: 'keyart 0 0.8 26 14 hud 0', off: 'sw no_ies 1', min: 4 },
  pugball: { start: 'stadium 2', settle: 500, cam: null, off: 'sw ies 0', min: 4 },
};
const field = async (name) => (await tool('wasm', { op: 'read', name })).value;
const mean = (p) => { const i = readImage(p); let s = 0; for (let k = 0; k < i.rgba.length; k += 4) s += i.rgba[k] + i.rgba[k + 1] + i.rgba[k + 2]; return s / (i.rgba.length / 4) / 3; };
const differ = (a, b) => { const x = readImage(a), y = readImage(b); let n = 0; for (let k = 0; k < x.rgba.length; k += 4) if (Math.max(Math.abs(x.rgba[k] - y.rgba[k]), Math.abs(x.rgba[k + 1] - y.rgba[k + 1]), Math.abs(x.rgba[k + 2] - y.rgba[k + 2])) > 16) n++; return n / (x.rgba.length / 4); };
let fails = 0;
const say = (ok, line) => { if (!ok) fails++; console.log(`${ok ? 'ok  ' : 'FAIL'} ${line}`); };
for (const backend of BACKENDS) {
  for (const game of GAMES) {
    const G = GAME[game];
    await load(game, backend);
    await tool('frame', { op: 'step', frames: 400 });
    await cmd(G.start, 600);
    await tool('frame', { op: 'step', frames: G.settle });
    if (G.cam) await cmd(G.cam);
    await tool('input', { op: 'press', button: 'start' }); // paused: the same moment both ways
    await tool('frame', { op: 'step', frames: 30 });
    const on = join(OUT, `${game}-${backend}-ies.png`), off = join(OUT, `${game}-${backend}-plain.png`);
    await tool('frame', { op: 'screenshot', path: on });
    const nOn = await field('lights.ies');
    await cmd(G.off);
    await tool('frame', { op: 'step', frames: 10 });
    await tool('frame', { op: 'screenshot', path: off });
    const nOff = await field('lights.ies');
    say(nOn >= G.min, `${game} ${backend}: ${nOn} floods drawn with their profile (at least ${G.min})`);
    say(!(nOff >= G.min), `${game} ${backend}: control (${G.off}) draws ${nOff} with a profile, so the count check fails without them`);
    const d = differ(on, off), mOn = mean(on), mOff = mean(off);
    say(d >= 0.002, `${game} ${backend}: the profile changes ${(d * 100).toFixed(2)}% of the picture by more than 16 levels (at least 0.2%)`);
    say(mOn >= 0.98 * mOff, `${game} ${backend}: mean level ${mOn.toFixed(2)} with the profile against ${mOff.toFixed(2)} without (not under 98%)`);
  }
}
await bye(fails ? 1 : 0);
